window.kbPageData["views/entry/k-63a9fc5fc2cfc871"] = {"key":"entry/k-63a9fc5fc2cfc871","state":{"route":"entry/k-63a9fc5fc2cfc871"},"node":{"id":"k-63a9fc5fc2cfc871","mode":"k","title":"累计值与单期值","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["单期值等于本期末累计值减去上期末累计值"],"qs":["江苏 2024 C类 行测#116","江苏 2024 C类 行测#117","江苏 2024 C类 行测#118"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":3,"directorySummary":"对可以按期相加的流量指标，在统计口径一致、累计起点相同的条件下，较晚截止的累计值减去较早截止的累计值，等于两个截止时点之间的发生量。","review":{"title":"累计值与单期值","type":"原理与机制","definition":"对可以按期相加的流量指标，在统计口径一致、累计起点相同的条件下，较晚截止的累计值减去较早截止的累计值，等于两个截止时点之间的发生量。","explanation":"两个累计截止时点相隔一个统计期时，差额就是该期的单期值。以年初为累计起点时，第一季度累计值就是第一季度的单期值。若只给出各累计期间的总体值和部分占比，应先按各期对应的占比求出部分累计值，再相减得到该部分的单期值。","basis":"据关联原题和解析编释。","references":[],"examFocus":{"江苏 2024 C类 行测#116":"用工业用电量表中两年的累计值分别还原第二季度用电量，再求同比增量。","江苏 2024 C类 行测#117":"按各自的年度累计区间还原单季进出口总额，再跨年比较。","江苏 2024 C类 行测#118":"用各期累计地区生产总值和同期第三产业占比先求累计增加值，再用相邻期的累计增加值还原单季值。"}},"aspects":[{"title":"已知累计值求单季值","uses":[{"unit":"Q1","role":"解题依据","use":"江苏 2024 C类 行测第116题。分别用2023年和2022年上半年累计工业用电量扣除各自第一季度用电量，得到第二季度用电量92亿和88.2亿千瓦时，同比增加3.8亿千瓦时，选B。","evidence":"（173.3-81.3）-（169.8-81.6）","qids":["江苏 2024 C类 行测#116"]},{"unit":"Q2","role":"解题依据","use":"江苏 2024 C类 行测第117题。将各年累计进出口总额换算为单季值后比较，2022年第四季度为6292.0减4566.0，得1726亿元，在所问区间内最高，选C。","evidence":"2022年第四季度=6292.0-4566.0","qids":["江苏 2024 C类 行测#117"]}]},{"title":"由累计总体值和占比求单季部分值","uses":[{"unit":"Q3","role":"解题依据","use":"江苏 2024 C类 行测第118题。将2023年上半年和第一季度累计地区生产总值分别乘以同期第三产业占比64.8%和65.4%，再将所得的两个累计增加值相减，得第二季度第三产业增加值约2623亿元，选A。","evidence":"8317.0×64.8%-4230.0×65.4%","qids":["江苏 2024 C类 行测#118"]}]}]},"questions":{"江苏 2024 C类 行测#116":{"paper":"江苏 2024 C类 行测","n":116,"mod":"资料分析","src":["3f1ec77ae8a18519b57e.pdf",25],"asrc":["02d6b49839583bdaf297.pdf",35],"card":"e04cb0e7042cc9f3a063a348","links":[{"id":"k-63a9fc5fc2cfc871","role":"解题依据","why":"各年的第二季度用电量须由同年上半年与第一季度的累计值相减得到。"}]},"江苏 2024 C类 行测#117":{"paper":"江苏 2024 C类 行测","n":117,"mod":"资料分析","src":["3f1ec77ae8a18519b57e.pdf",25],"asrc":["02d6b49839583bdaf297.pdf",35],"card":"e04cb0e7042cc9f3a063a348","links":[{"id":"k-63a9fc5fc2cfc871","role":"解题依据","why":"单季进出口总额须扣除当年此前季度的累计额。"}]},"江苏 2024 C类 行测#118":{"paper":"江苏 2024 C类 行测","n":118,"mod":"资料分析","src":["3f1ec77ae8a18519b57e.pdf",25],"asrc":["02d6b49839583bdaf297.pdf",36],"card":"e04cb0e7042cc9f3a063a348","links":[{"id":"k-63a9fc5fc2cfc871","role":"解题依据","why":"从上半年累计值中扣除第一季度累计值，得到第二季度的单季值。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-63a9fc5fc2cfc871":[["江苏 2024 C类 行测#116"],["江苏 2024 C类 行测#117"],["江苏 2024 C类 行测#118"]]}};
